@dataclass
class FrpTaskParam:
    """
    King 2024-09-09 17:53

    Frp 任务参数
    Params:
       name: 对应 Frp 中的特征名称
       params: 对应 Frp 中的特征参数
       sof: Sof
       enable_extra: 是否开启保存中间事件数据, 一般在优化器优化时不开启，单独运行则开启
    """

    name: str
    params: Dict[str, Any]
    sof: Sof
    enable_extra: bool = False

    def for_json(self) -> str:
        sof = self.sof
        app = dict(
            env_name=settings.ENV,
            app_dir=settings.APP_DIR,
            enable_extra= 1 if self.enable_extra else 0
        )
        return dict(
            name=self.name,
            params=JsonUtil.dumps(self.params),
            sof=dict(
                sof_name=sof.sof_name,
                stk_tlist=sof.stk_tlist,
                startDay=sof.startDay,
                endDay=sof.endDay,
                full_period=sof.full_period
            ),
            app=app,
        )

    # 保留旧版函数
    def to_dict(self) -> dict:
        return self.for_json()

class FrpMixIn(JsonParamPathMixIn):
    """
    Author: King
    Since : 2023-01-05 10:31
    Desc  :
       - Frp 混入类
    """

    @property
    def that(self) -> AbsFao:
        return self

    def hold_cal_type(self):
        return CalType.Cache

    @property
    def Dao(self):
        return FrpDbaDao(self)

    def to_df(self):
        """ 没有 adt 数据时的默认 to_df 实现"""
        dfs = list(self.that.F.values())
        if len(dfs) == 1:
            return dfs[0]
        return pd.concat(dfs, axis=1, join="outer")

    def to_dfs(self):
        return self.that.F

    def doFrpTarget(self) -> dict:
        """优化目标"""
        return self.that.tar_type.doFrpTarget()

    def doFrpUpSource(self) -> Union[List[FaoType],Dict]:
        """Frp 特征需要保存的上游特征数据源, 默认 params 中的 Fao 类型"""
        return list(self.that.P.values())

    def doFrpTaskParam(self,run_ups=True,enable_extra=False) -> FrpTaskParam:
        """Frp 程序运行需要的相关数据
        Params:
            run_ups: True 表示需要运行上游特征，确保数据保存到 dba
            enable_extra: 是否开启保存中间事件数据, 一般在优化器优化时不开启，单独运行则开启
        """
        that = self.that

        if run_ups and that.prop_on_run_ups:
            self._run_ups()

        with CurrFrpEnv():
            return FrpTaskParam(
                name=that.alias,
                params=that.for_json(),
                sof=that.sof,
                enable_extra=enable_extra,
            )

    def _run_ups(self):
        ups = self.doFrpUpSource()
        if isinstance(ups,dict):
            ups = list(ups.values())
        if ups:
            for v in ups:
                if isinstance(v, FaoType):
                    self._run_up(v)

    def _run_up(self, up: FaoType):
        """运行上游特征"""
        ttype = self.that.tar_type
        if ttype.isBlockSet():  # 板块集特征
            # 上游特征是板块特征， children 一定是板块集，则需要对每个板块运行
            if up.tar_type.isNormalBlock():
                for blk in ttype.children():
                    with CurrIndustry(blk):
                        up.run()
                return

        if ttype.isNormalBlock():  # 板块特征
            # 上游特征是单品种特征，则需要对每个品种运行
            if up.tar_type.isSymbol():
                for sym in ttype.symbols():
                    with CurrSymbol(sym):
                        up.run()
                return
        up.run()

    def dump(self, *args, **kwargs):
        # python 端不再保存相关信息
        pass

    def _impl(self):
        logger = self.that.logger

        # 保存 frp 需要的参数到 json 文件中
        ts = TimeUtil.now_str("%Y%m%d%H%M%S")
        import uuid

        linker = FrpTaskLinker(
            task_name=f"{self.that.alias}.{ts}!{uuid.uuid1()}",
            target=self.doFrpTarget(),
            task_params=self.doFrpTaskParam(enable_extra=True),
        )
        json_path = linker.rerun(CalType.Gen).F.value
        poc_file = "./frp/trade-poc/edh_modules/trade/frp/worker/one.edh"
        # poc_file = (
        #     "./frp/trade-poc/edh_modules/trade/frp/worker/one.edh +RTS -sstderr -RTS"
        # )
        # poc_file = "./frp/trade-poc/edh_modules/trade/frp/worker/one.edh +RTS -hy -p -RTS"

        # 启动进程运行 frp 程序
        import subprocess

        args = [
            f"--f={poc_file}",
            f"--jp={json_path}",
        ]
        args = " ".join(args)
        process = subprocess.Popen(
            f"epm exec ts {args}",
            # f"stack exec -- ts {args}",
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            encoding="utf-8",
            cwd=os.getenv("M3WORKS") + "/edh-universe",  # 工作区默认使用M3WORKS
        )

        success = True
        for line in iter(process.stdout.readline, "b"):
            msg = f"{line.rstrip()}"
            logger.info(msg)

            # 检测到退出异常则表示优化失败
            if msg.startswith(("SystemExit:",)):
                logger.warning(f"⛔ 检测到异常日志，即将退出优化 ......")
                success = False
                break

            if not subprocess.Popen.poll(process) is None:
                if line == "":
                    success = True
                    break
        if success:
            success = process.poll() == 0

        # 删除任务文件
        if os.path.exists(json_path):
            os.remove(json_path)

        if not success:
            raise RuntimeError(
                f"⛔ {self.that.ppname} for {self.that.tar_name} 执行异常"
            )

        # 加载数据
        res = self.that.load()
        if not res and not isinstance(res, dict):
            raise Exception(
                f"{self.that.ppname} not find save result for {self.that.tar_name}: {res}"
            )
        return res

    def load_extra(self) -> dict:
        """ 获取 Frp 保存的中间特征数据 """
        return FrpExtraDbaDao(self).load()


class FrpTaskLinker(CacheMixIn, FunctionFao):
    """
    Author: King
    Since : 2022-01-26 14:48
    Desc  :
        - 任务链接
    Params:
       task_name: 任务名称
    """

    params = lambda: {
        "task_name": None,
        "target": None,
        "task_params": None,
    }

    # 不启动优化时间范围
    def hold_on_date_range(self):
        return False

    # 不执行上游特征
    def _run_ups(self):
        pass

    @property
    def root_dir(self):
        return settings.MQUANT_TASK_DIR

    @property
    def full_dir(self):
        ip = get_host_ip()
        if ip is None:
            ip = "localhost"
        return "/".join(
            [self.root_dir, "frp", settings.ENV, ip, TimeUtil.now_str("%Y%m%d")]
        )

    @property
    def link_path(self):
        return f"{self.full_dir}/{self.P.task_name}.json"

    def _impl(self):
        return dict(value=self.link_path)

    def load(self, *args, **kwargs):
        if os.path.isfile(self.link_path):
            return dict(value=self.link_path)
        return None

    def dump(self, *args, **kwargs):
        res = {
            "target": self.P.target.for_json(),
            "task_params": self.P.task_params.for_json(),
        }
        JsonUtil.dump2(res, self.link_path)
        self.logger.info(f"📘 save frp task json: {self.link_path}")

