class FaoField(metaclass=abc.ABCMeta):
    """ 字段类型基类 """

    @abc.abstractmethod
    def exist_state_field(self):
        """是否存在状态型字段"""
        pass

    @abc.abstractmethod
    def exist_event_field(self):
        """是否存在事件型字段"""
        pass

    @abc.abstractmethod
    def fit_dictfield(self, df: pd.DataFrame) -> "DictField":
        """ 根据 DataFrame 解析字段类型 """
        pass

    def get(self, key: str, default=None) -> "NormalField":
        """ 获取字段类型 """
        return None


class NormalField(FaoField):
    """ 普通字段类型"""
    dtype: str = None

    # 默认值
    default_val = None

    def redtype(self):
        return "f8"

    # 默认值
    def default(self):
        return self.default_val

    def fit_dictfield(self, df: pd.DataFrame):
        """所有字段都使用相同的字段类型"""
        return DictField({name: self for name in df.columns})

    def exist_state_field(self):
        """是否存在状态型字段"""
        return self.is_state_field()

    def exist_event_field(self):
        return self.is_event_field()

    # 是否事件型字段
    def is_event_field(self):
        return False

    # 是否 adt 型字段
    def is_adt_field(self):
        return False

    # 是否Bool型字段
    def is_bool_field(self):
        return False

    # 是否 状态 型字段
    def is_state_field(self):
        return False

    # 过时函数
    def is_status_field(self):
        return self.is_state_field()

    # 填充 状态型
    def is_fill_state_field(self):
        return False

    def fit_df(self, df: pd.DataFrame) -> pd.DataFrame:
        # 根据字段类型解析字段
        raise NotImplementedError(self.__class__.__name__)

    FDTYPE_PREFIX = None

    def to_fdtype(self):
        """ 字段数据类型 """
        if self.FDTYPE_PREFIX is None:
            return self.dtype
        return f"{self.FDTYPE_PREFIX}@{self.dtype}"

    @classmethod
    def from_str(cls, fdtype: str):
        fld = EventField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _BoolEventField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _NanEventField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _Nan0EventField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _StatusEventField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _StatusBoolEventField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _FloatField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _IntField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = _DateTimeField.from_str(fdtype)
        if fld is not None:
            return fld

        fld = AdtEventField.from_str(fdtype)
        if fld is not None:
            return fld

        raise Exception(f"Unknown fdtype {fdtype}")

    def __repr__(self):
        return f"{type(self).__name__}()"

    def __call__(self, *args, **kwargs):
        return self.__class__(*args, **kwargs)


class _DataFrameField(FaoField):
    """
    自动根据 DataFrame 解析字段类型
    只能应用在 DataFrame 特征中
    """

    __slots__ = ()

    def exist_state_field(self):
        return False

    def exist_event_field(self):
        return False

    def fit_dictfield(self, df: pd.DataFrame) -> "DictField":
        res = {}
        for k, v in df.dtypes.items():
            res[k] = NormalField.from_str(v.name)
        return DictField(res)

    def __repr__(self):
        return f"DataFrameField"

    def __call__(self, *args, **kwargs):
        return self.__class__(*args, **kwargs)


DataFrameField = _DataFrameField()


class SharedTsField(FaoField):
    """
    暂时针对 Frp 输出一个时间轴多个字段设计
    """

    __slots__ = ("fld", "name", "dtype")

    def __init__(self, name: str, fld: NormalField):
        self.name = name # 字段名称
        self.fld = fld  # 字段类型 
        self.dtype = fld.dtype # dtype 类型

    def exist_state_field(self):
        """是否存在状态型字段"""
        return self.fld.exist_state_field()

    def exist_event_field(self):
        """是否存在事件型字段"""
        return self.fld.exist_event_field()

    def fit_dictfield(self, df: pd.DataFrame) -> "DictField":
        return self.fld.fit_dictfield(df)

    def get(self, key: str, default=None) -> "NormalField":
        return self.fld.get(key, default)

    def __getattr__(self,key):
        """ 其他属性从 fld 中获取 """
        return getattr(self.fld,key)

    def __repr__(self):
        return f"SharedTsField(name={self.name!r},fld={self.fld!r})"


class MvField(FaoField):
    """
    暂时针对 Frp 输出一个时间轴多个字段设计
    """

    __slots__ = ("fld", "names", "dtype")

    def __init__(self, names: List[str], fld: NormalField):
        """
        @names: 字段名称列表
        @fld: 同一个的字段类型
        """
        self.fld = fld
        self.names = names
        self.dtype = {name: fld.dtype for name in names}

    def exist_state_field(self):
        """是否存在状态型字段"""
        return self.fld.exist_state_field()

    def exist_event_field(self):
        """是否存在事件型字段"""
        return self.fld.exist_event_field()

    def fit_dictfield(self, df: pd.DataFrame) -> "DictField":
        raise NotImplementedError(self.__class__.__name__)

    def get(self, key: str, default=None) -> "NormalField":
        if key not in self.names:
            raise KeyError(f"MvField: {key} not in {self.names}")
        return SharedTsField(name=key, fld=self.fld)

    def to_dict(self):
        return {key: SharedTsField(name=key, fld=self.fld) for key in self.names}

    def __iter__(self):
        for key in self.names:
            yield self.get(key)        

    def __len__(self):
        return len(self.names)

    def __repr__(self):
        return f"MvField(names={self.names!r},fld={self.fld!r})"


class DictField(FaoField):
    """字典字段，值为 NormalField 子类"""

    __slots__ = ("ds",)

    def __init__(self, ds: Dict[str, NormalField]):
        if isinstance(ds, DictField):
            self.ds = ds
        elif isinstance(ds, dict):
            res = {}
            for k, v in Ndict.fold(ds).items():
                if not isinstance(v, (NormalField,MvField)):
                    raise Exception(
                        f"DictField value only support NormalField or MvField, {k} = {v}"
                    )
                res[k] = v
            self.ds = res
        else:
            raise Exception("DictField param ds must be dict")

    def __iter__(self):
        for k,v in self.items():
            yield k

    def fit_dictfield(self, df: pd.DataFrame):
        for k, fld in self.items():
            if k not in df:
                raise Exception(f"{k} not in DataFrame , {fld}")
        return self

    def exist_state_field(self):
        """是否存在状态型字段"""
        for k, v in self.items():
            if v.exist_state_field():
                return True
        return False

    def exist_event_field(self):
        for k, v in self.items():
            if v.exist_event_field():
                return True
        return False

    def items2(self):
        nds: Dict[str, FaoField] = Ndict(self.ds)
        for k, v in nds.items():
            if isinstance(v, FaoField):
                yield (k, v)
            elif isinstance(v, dict):
                yield (k, DictField(v))
            else:
                raise Exception(f"DictField items2 error: {k} = {v}")

    def items(self):
        for k, v in self.ds.items():
            yield (k, v)

    def fields(self) -> List[str]:
        res = []
        for k, fld in self.ds.items():
            if isinstance(fld, MvField):
                # TODO
                res.extend([f"{k}.{name}" for name in fld.names])
            else:
                res.append(k)

        return res

    def to_fdtypes(self) -> dict:
        """ 获取所有字段数据类型 """
        res = {}
        for k, fld in self.ds.items():
            if isinstance(fld, NormalField):
                res[k] = fld.to_fdtype()
            else:
                raise Exception(f"DictField fdtypes error: {k} = {fld}")
        return res

    def keys(self) -> List[str]:
        return list(self.ds.keys())

    def gets(self, key: str, default=None) -> NormalField:
        return Ndict(self.ds).gets(key, default)

    def get(self, key: str, default=None) -> NormalField:
        return Ndict(self.ds).get(key, default)

    def __repr__(self):
        return f"{type(self).__name__}({self.ds!r})"


class _FloatField(NormalField):
    """
    float Bar型字段,只支持 f8
    """

    __slots__ = ("dtype",)

    default_val = np.NaN

    RULES = {
        "f8": "f8",
        "f4": "f4",
        "float64": "f8",
        "float32": "f4",
    }

    def __init__(self, dtype: str = "f8"):
        dt = self.RULES.get(dtype)
        if dt is None:
            raise Exception(f"Unknown Float dtype {dtype}")
        self.dtype = dt

    @classmethod
    def from_str(cls, fdtype: str):
        if fdtype in cls.RULES:
            return cls(fdtype)
        return None

    def fit_df(self, df: pd.DataFrame):
        return df

    def __repr__(self):
        return f"FloatField(dtype = {self.dtype!r})"


FloatField = _FloatField()


class _IntField(NormalField):
    """
    Int Bar型字段,默认 i8 ,只支持 i1 i8
    nan 替换为 0
    """

    __slots__ = ("dtype",)

    RULES = {
        "i8": "i8",
        "i1": "i1",
        "int8": "i1",
        "int64": "i8",
    }

    default_val = 0

    def __init__(self, dtype: str = "i8"):
        dt = self.RULES.get(dtype)
        if dt is None:
            raise Exception(f"Unknown Int dtype {dtype}")
        self.dtype = dtype

    @classmethod
    def from_str(cls, fdtype: str):
        if fdtype in cls.RULES:
            return cls(fdtype)
        return None

    def fit_df(self, df: pd.DataFrame):
        return df.replace(np.NaN, 0)

