class EventField(NormalField):
    """
    事件型字段
    """

    __slots__ = ("dtype", "default_val", "dropna", "drop0")

    RULES = {
        "f8": "f8",
        "f4": "f4",
        "float64": "f8",
        "Double": "f8",
        "float32": "f4",
        "i8": "i8",
        "Int": "i8",
        "i1": "i1",
        "int8": "i1",
        "int64": "i8",
    }

    FDTYPE_PREFIX = "event"

    @classmethod
    def from_str(cls, fdtype: str):
        xs = fdtype.split("@")
        if len(xs) == 2 and xs[0] == cls.FDTYPE_PREFIX:
            return cls(xs[1])
        return None

    def is_event_field(self):
        return True

    def __init__(
        self,
        dtype: str = "f8",
        default_val=np.NaN,
        dropna: bool = False,
        drop0: bool = False,
    ):
        dt = self.RULES.get(dtype)
        if dt is None:
            raise Exception(f"Unknown Event dtype {dtype}")
        self.dtype = dt
        self.default_val = default_val
        self.dropna = dropna
        self.drop0 = drop0

    def fit_df(self, df: pd.DataFrame):
        if self.drop0:
            df = df.replace(0, np.NaN)
        if self.dropna:
            df = df.dropna()
        return df

    def __repr__(self):
        return f"{type(self).__name__}({self.dtype!r},{self.default_val!r},{self.dropna!r},{self.drop0!r})"


