class DbaUtil:
    """ dba 读写工具类 """

    @classmethod
    def dbarray(
        cls, full_dir, file_name, dt=f8, shape=None, access=mmap.ACCESS_READ
    ) -> DbArray:
        bwrite = access == mmap.ACCESS_WRITE
        if bwrite:
            file_path = f"{full_dir}/{file_name}.dba"

            temp_file_name = f"{file_name}_{uuid.uuid1()}"
            temp_path = f"{full_dir}/{temp_file_name}.dba"

            res = DbArray(full_dir, temp_file_name, dt, shape, access=access)

            if hasattr(res,"flush"):
                res.flush()

            os.rename(temp_path, file_path)
            return res
        return DbArray(full_dir, file_name, dt, shape, access=access)

    @classmethod
    def read_ndarray(cls, full_dir,file_name, dt=f8):
        return cls.dbarray(
            full_dir,file_name, dt, shape=None, access=mmap.ACCESS_READ
        ).ndarray

    @classmethod
    def write_array(cls, full_dir,file_name, dt=f8, shape=None) -> "DbArray":
        return cls.dbarray(
            full_dir, file_name, dt, shape, access=mmap.ACCESS_WRITE
        )

    @classmethod
    def read_field_ts(cls, full_dir,field:str=None,is_event:bool=False,key:str = None):
        """ 读取字段时间轴 
        key 不为None，表示两层，如 Datarame 型特征
        """
        tsPath = None
        if is_event:
            tsPath = f"{key}.{field}.{TS_PATH_NAME}" if key else f"{field}.{TS_PATH_NAME}"
        else:
            tsPath = f"{key}.{TS_PATH_NAME}" if key else TS_PATH_NAME
        return DbaUtil.read_ndarray(full_dir, tsPath, "M8[ns]")

    @classmethod
    def dump(cls, df:pd.DataFrame, full_dir:str, flds: DictField):
        """
        Author: King
        Since : 2024-08-26 15:53
        Desc  :
            - 事件型字段一个字段保存一个时间轴
            - 所有Bar型字段保存一个时间周期
        """
        hasBar = False
        for field, fld in flds.items():
            ds = fld.fit_df(df[field])
            n = ds.shape[0]

            val = cls.write_array(full_dir, field, fld.dtype, n)
            val.len1d = n
            val.ndarray[:] = ds.values

            # 事件型需要保存自己的时间轴
            if fld.is_event_field():
                ts = cls.write_array(full_dir, f"{field}.{TS_PATH_NAME}", i8, n)
                ts.len1d = n
                ts.ndarray[:] = ds.index.values
            else:
                hasBar = True

        if hasBar:
           n = df.shape[0]
           ts = cls.write_array(full_dir, TS_PATH_NAME, i8, n)
           ts.len1d = n
           ts.ndarray[:] = df.index.values

    @classmethod
    def dumpWithKey(
        cls, key: str, df: pd.DataFrame, full_dir: str, flds: DictField
    ):
        """
        King 2023-03-10 10:21
        Desc  :
            - 事件型字段一个字段保存一个时间轴
            - 所有Bar型字段保存一个时间周期
        params:
            key: 保存一个字典中的多个DataFrame时，key为df在字典中对应的key
        """
        hasBar = False
        for field, fld in flds.items():
            ds = fld.fit_df(df[field])
            n = ds.shape[0]

            val = cls.write_array(full_dir, f"{key}.{field}", fld.dtype, n)
            val.len1d = n
