import numpy as np
import hbi
from typing import Callable,Union

from ...lib3 import is_float
from .internal import HasPropertyFunc, HasPPDict, Ndict, ppshow, CurrFaoRepr

__all__ = [
    "enjson",
    "enjson2",
    "dejson",
    "dejson2",
    "eval2",
    "EvalCtx",
    "StringFn",
]


def enjson(ips, enlist=True, ennone=True):
    """
    Author: King
    Since : 2022-08-04 14:07
    Desc  :
        - 字典参数跨平台 json 转换
        - 将不是字符串或者数字的值,前后加*转换为字符串
    Params:
       enlist: list列表是否加*转换
       ennone: None 值是否加*转换
    """

    def go(value):
        if isinstance(value, dict):
            return {k: go(v) for k, v in value.items()}
        # list 也加**，因为csv不认识list

        if not enlist:
            if isinstance(value, list):
                return [go(v) for v in value]

            if isinstance(value, tuple):
                return tuple([go(v) for v in value])

        if not ennone and value is None:
            return value

        if isinstance(value, float) and not np.isfinite(value):
            return f"*{value}*"
        if isinstance(value, (str, int, float, bool)) or is_float(str(value)):
            return value
        return f"*{value}*"

    with CurrFaoRepr(): # 特征对象只显示输入参数
        if isinstance(ips, dict):
            return {k: go(v) for k, v in Ndict.fold(ips).items()}
        if isinstance(ips, HasPPDict):
            return f"*{ips.__class__.__name__}({ppshow(ips.ppdict)})*"
        if isinstance(ips,(list,tuple)):
            return [go(v) for v in ips]
        return f"*{ips}*"


def enjson2(ips):
    """
    Author: King
    Since : 2022-08-04 14:10
    Desc  :
        - list列表,None不转换
    """
    return enjson(ips, False, False)


class _EvalCtx:
    __slots__ = ["_json_ctx"]

    def __init__(self):
        self._json_ctx = None

    @property
    def json_ctx(self):
        if self._json_ctx is None:
            import importlib

            self._json_ctx = importlib.import_module("m3sof.settings.json")
        return self._json_ctx

    @property
    def tis_ctx(self):
        return self.json_ctx

    def tis_vars(self, other=None):
        res = vars(self.tis_ctx)
        if other:
            res.update(other)
        return res


EvalCtx = _EvalCtx()


def dejson(ips:Union[dict,str]):
    """
    如果value的值前后有*,则去掉后eval

    一般用于从csv或者数据库读取的参数,通过enjson后的参数，eval回原有的类型
    """
    def go(v):
        if isinstance(v, str):
            if v.startswith("*") and v.endswith("*"):
                return hbi.run_in_context(v[1:-1], vars(EvalCtx.json_ctx))
            return v
        if isinstance(v, dict):
            return {k1: go(v1) for k1, v1 in v.items()}
        if isinstance(v, list):
            return [go(v1) for v1 in v]
        return v

    if isinstance(ips,str):
        ips = eval2(ips)

    assert isinstance(ips, dict), f"dejson ips:{ips} is not dict"
    return {k: go(v) for k, v in ips.items()} if isinstance(ips, dict) else ips


def dejson2(ips):
    """
    如果value的值前后有*,则去掉后eval

    一般用于从csv或者数据库读取的参数,通过enjson后的参数，eval回原有的类型
    """
    def go(v):
        if isinstance(v, str):
            if v.startswith("*") and v.endswith("*"):
                return hbi.run_in_context(v[1:-1], vars(EvalCtx.json_ctx))
            # 处理老版本list未处理的情况
            if v.startswith("[") and v.endswith("]"):
                return hbi.run_in_context(v, vars(EvalCtx.json_ctx))
            return v
        if isinstance(v, dict):
            return {k1: go(v1) for k1, v1 in v.items()}
        if isinstance(v, list):
            return [go(v1) for v1 in v]
        return v

    return {k: go(v) for k, v in ips.items()} if isinstance(ips, dict) else ips


def eval2(s: str,**defs):
    vs = vars(EvalCtx.json_ctx)
    return hbi.run_in_context(s, vs,defs)


class StringFn(HasPropertyFunc):
    """
    Author: King
    Since : 2022-09-06 17:04
    Desc  :
        - 字符串形式实现lambda函数，可以作为特征类的参数
        - 注意字符串中的空格等都会影响参数路径,请统一按照格式规范书写
    Params:
       code: lambda 函数代码字符串
    Example:
        >>> StringFn("lambda x:x > 0")
    """

    __slots__ = ["code"]

    def __init__(self, code: str):
        self.code = code

    @property
    def func(self) -> Callable:
        return eval2(self.code)

    def __call__(self, *args, **kwargs):
        return self.func(*args, **kwargs)

    def __repr__(self):
        return f"{type(self).__name__}({self.code!r})"

