def _same_feature(left, right):
    return left.alias == right.alias and left.ggjson == right.ggjson


def _distinct_features(*features):
    result = []
    for feature in features:
        if not any(_same_feature(feature, existing) for existing in result):
            result.append(feature)
    return result


def _lane_max_grade(feature, expected_family):
    mapping = feature.P.lane_threshold_map
    values = mapping.get(expected_family)
    if not values:
        raise ValueError(
            f"{feature.alias} does not expose a nonempty {expected_family} lane"
        )
    return len(values)


def _p1_snapshot(*features):
    digest = hashlib.sha256()
    for feature in features:
        digest.update(feature.alias.encode("utf-8"))
        digest.update(b"\0")
        digest.update(feature.ggjson.encode("utf-8"))
        digest.update(b"\0")
    return "p1-params-sha256:" + digest.hexdigest()


def _build_p2_params(wall, build, attack, absorb):
    for label, dependent in (
        ("BuildAssembler.wall", build.P.wall),
        ("AttackFlowAssembler.wall", attack.P.wall),
        ("AbsorbAssembler.wall", absorb.P.wall),
    ):
        if not _same_feature(wall, dependent):
            raise ValueError(f"{label} must be the exact selected WallAssembler")

    tactical = attack.P.directed_large_deal_tactical
    structural = attack.P.directed_large_deal_structural
    max_distance = int(attack.P.p_attack_ticks)
    retreat_boundary = attack.P.p_retreat_ticks
    if retreat_boundary is None:
        retreat_boundary = 2 * max_distance

    wall_root = EawP1WallLifecycleFrp(
        wallLifecycleInput=WallOccurrenceFao(wallOccurrenceSource=wall)
    )
    build_root = EawP1BuildActivityFrp(
        buildActivityInput=BuildOccurrenceFao(
            buildOccurrenceSource=build,
            buildWallSource=wall,
        )
    )
    attack_root = EawP1AttackSegmentBookFrp(
        attackSegmentInput=AttackSegmentFao(
            attackSegmentSource=attack,
            attackSegmentWallSource=wall,
        ),
        attackFormationInput=FormationEvidenceFao(
            formationEvidenceSource=attack,
            formationEvidenceWallSource=wall,
        ),
        attackBarrierInput=WallBarrierFao(
            wallBarrierSource=attack,
            wallBarrierWallSource=wall,
        ),
    )
    absorb_root = EawP1AbsorbInteractionFrp(
        absorbInteractionInput=AbsorbOccurrenceFao(
            absorbOccurrenceSource=absorb,
            absorbWallSource=wall,
        )
    )
    return {
        "eawBattleWallLifecycleInput": wall_root,
        "eawBattleBuildActivityInput": build_root,
        "eawBattleAttackSegmentBookInput": attack_root,
        "eawBattleAbsorbInteractionInput": absorb_root,
        "eawBattleAppliedTacticalMaxGrade": _lane_max_grade(
            tactical, "tactical"
        ),
        "eawBattleAppliedStructuralMaxGrade": _lane_max_grade(
            structural, "structural"
        ),
        "eawBattleAppliedMaxEligibleDistance": max_distance,
        "eawBattleAppliedRetreatBoundaryTicks": int(retreat_boundary),
        "eawBattleAppliedA3Gap": int(attack.P.t_gap_attack_ticks),
        "eawBattleSourceParameterSnapshot": _p1_snapshot(
            wall, build, attack, absorb
        ),
    }


def _default_p2_params():
    wall = WallAssembler()
    build = BuildAssembler(wall=wall)
    tactical = DirectedBigDealTick()
    structural = DirectedBigDealTick(
        parameter_set_id="structural-default",
        qualification_family="structural",
        lane_threshold_map=FAnyParam(
            {"structural": ["0.997", "0.999"]}
        ),
    )
    attack = AttackFlowAssembler(
        wall=wall,
        directed_large_deal_tactical=tactical,
        directed_large_deal_structural=structural,
    )
    absorb = AbsorbAssembler(wall=wall)
    return _build_p2_params(wall, build, attack, absorb)


def _clean(value):
    try:
        return None if pd.isna(value) else value
    except (TypeError, ValueError):
        return value


def _parent_groups(frame, builder):
    if frame.empty:
        return {}
    parent_levels = list(range(frame.index.nlevels - 1))
    result = {}
    for key, group in frame.groupby(
        level=parent_levels, sort=False, dropna=False
    ):
        if len(parent_levels) == 1 and isinstance(key, tuple) and len(key) == 1:
            key = key[0]
        result[key] = tuple(builder(row) for _, row in group.iterrows())
    return result


def _record(row, fields):
    result = {}
    for field in fields:
        present_field = field + "_present"
        if present_field in row.index and int(row[present_field]) != 1:
            result[field] = None
        else:
            result[field] = _clean(row[field])
    return result


def _with_optional_paths(fields, optional_columns):
    result = dict(fields)
    for column in optional_columns:
        result[column + "_present"] = result[column] + "Present"
    return result


def _restore_optionals(frame, optional_columns):
    for column in optional_columns:
        present = frame.pop(column + "_present")
        frame[column] = frame[column].astype("object")
        frame.loc[present != 1, column] = None
    return frame


def _attach(base, column, grouped, default=()):
    base[column] = pd.Series(index=base.index, dtype="object")
    for key in base.index:
        base.at[key, column] = grouped.get(key, default)
    return base


def _empty_event_frame(columns, depth):
    if depth == 1:
        index = pd.Index([], dtype="datetime64[ns]")
    elif depth == 2:
        index = pd.MultiIndex.from_arrays(
            [[], []], names=[None, "record_id"]
        )
    elif depth == 3:
        index = pd.MultiIndex.from_arrays(
            [[], [], []], names=[None, "record_id", "subrecord_id"]
        )
    else:
        raise ValueError(f"unsupported ADT index depth: {depth}")
    return pd.DataFrame(index=index, columns=columns)


def _is_vector_getter(value):
    return all(hasattr(value, name) for name in ("seq", "idxs", "ridxs"))


def _indexed_values(getter, array):
    if getter.idxs is None:
        return array.ndarray
    return array.ndarray[getter.idxs]


def _decode_text_field(getter, array):
    values = _indexed_values(getter, array)
    store = getter.seq.__store__
    if "::[Text]$Data.Text" in array.data_path:
        decoded = [store.load_TextList(int(pointer)) for pointer in values]
        lengths = np.fromiter(
            (len(items) for items in decoded), dtype=np.int64, count=len(decoded)
        )
        if lengths.sum() == 0:
            ridxs = np.empty(
                (getter.ridxs.shape[0] + 1, 0), dtype=np.int64
            )
            return [], ridxs
        parent_columns = np.repeat(
            np.arange(len(decoded), dtype=np.int64), lengths
        )
        subrecord_ids = np.concatenate(
            [np.arange(length, dtype=np.int64) for length in lengths if length]
        )
        ridxs = np.vstack(
            [getter.ridxs[:, parent_columns], subrecord_ids]
        )
        return [item for items in decoded for item in items], ridxs
    if "::Text$Data.Text" in array.data_path:
        return [store.load_Text(int(pointer)) for pointer in values], getter.ridxs
    raise KeyError(array.data_path)


def _resolve_event_path(root_seq, path):
    current = root_seq
    parts = path.split(".")
    for position, part in enumerate(parts):
        terminal = position == len(parts) - 1
        parent = current
        try:
            current = current[part]
        except KeyError as exc:
            if not _is_vector_getter(parent):
                raise
            try:
                array = getattr(parent.seq, part)
            except AttributeError:
                raise exc
            if not terminal:
                raise exc
            return _decode_text_field(parent, array)

        if _is_vector_getter(current):
            if current.seq.count() == 0 and not terminal:
                # Empty nested lists legitimately have only their anchor file.
                # No child field arrays exist in that case.
                return [], np.empty(
                    (parent.ridxs.shape[0] + 1, 0), dtype=np.int64
                )
            if terminal:
                raise ValueError(f"ADT path ends at a nested structure: {path}")
            continue

        if terminal:
            if _is_vector_getter(parent):
                return current, parent.ridxs
            return current, np.arange(len(current), dtype=np.int64)[None, :]
        raise ValueError(f"ADT path reaches a scalar before its end: {path}")
    raise ValueError(f"empty ADT path: {path}")


class EawBattleP(FrpAdtDfMixIn, BaseSymbolFrpFao):
    """半秒 Tick 经正式 P1 typed products 到 P2 公共产品的 Fao。"""

    params = _default_p2_params

    @classmethod
    def from_p1_features(cls, *, wall, build, attack, absorb):
        """从本次实际选择的 P1 参数实例形成固定 FormationContext。"""
        return cls(**_build_p2_params(wall, build, attack, absorb))

    def doFrpUpSource(self):
        """只运行四个真实 TIS 产品；P1 typed Fao 在同一 Haskell 根内消费它们。"""
        wall = (
            self.P.eawBattleWallLifecycleInput.P.wallLifecycleInput.P.wallOccurrenceSource
        )
        build = (
            self.P.eawBattleBuildActivityInput.P.buildActivityInput.P.buildOccurrenceSource
        )
        attack = (
            self.P.eawBattleAttackSegmentBookInput.P.attackSegmentInput.P.attackSegmentSource
        )
        absorb = (
            self.P.eawBattleAbsorbInteractionInput.P.absorbInteractionInput.P.absorbOccurrenceSource
        )
        return [wall, build, attack, absorb]

    def to_df(self):
        raise TypeError(
            "EawBattleP has eight primary products and three membership "
            "streams; use to_dfs()"
        )

    def to_dfs(self):
        return {
            "BP-07": self._materiality_df(),
            "BP-08": self._continuity_df(),
            "BP-09": self._opened_df(),
            "BP-10": self._fate_df(),
            "BP-11": self._battle_scope_df(),
            "BP-12": self._battle_summary_df(),
            "BP-13": self._battle_window_df(),
            "BP-22": self._defense_activity_df(),
            "battle_attack_membership": self._battle_attack_membership_df(),
            "battle_attack_role": self._battle_attack_role_df(),
            "defense_activity_source_membership": self._defense_activity_source_membership_df(),
        }

    def _event_df(self, event, fields, depth):
        materialized = self.F.get(event)
        if materialized is None:
            extra = self.load_extra()
            materialized = None if extra is None else extra.get(event)
        if materialized is None:
            raise KeyError(f"missing canonical P2 public event: {event}")

        root_seq = materialized.value.root_seq
        if root_seq.count() == 0:
            return _empty_event_frame(fields.keys(), depth)

        data = {}
        common_ridxs = None
        for column, path in fields.items():
            try:
                values, ridxs = _resolve_event_path(root_seq, path)
            except Exception as exc:
                raise ValueError(
                    f"{event}.{column} cannot be read from ADT path {path}"
                ) from exc
            if ridxs.shape[0] != depth:
                raise ValueError(
                    f"{event}.{column} resolved to index depth "
                    f"{ridxs.shape[0]}, expected {depth}"
                )
            if common_ridxs is None:
                common_ridxs = ridxs
            elif not np.array_equal(common_ridxs, ridxs):
                raise ValueError(f"unaligned ADT fields in {event}")
            data[column] = values

        if common_ridxs is None or common_ridxs.shape[1] == 0:
            return _empty_event_frame(fields.keys(), depth)

        event_ts = materialized.ts
        time_index = event_ts[common_ridxs[0, :]]
        if depth == 1:
            index = time_index
        elif depth == 2:
            index = pd.MultiIndex.from_arrays(
                [time_index, common_ridxs[1, :]],
                names=[None, "record_id"],
            )
        elif depth == 3:
            index = pd.MultiIndex.from_arrays(
                [time_index, common_ridxs[1, :], common_ridxs[2, :]],
                names=[None, "record_id", "subrecord_id"],
            )
        else:
            raise ValueError(f"unsupported ADT index depth: {depth}")
        return pd.DataFrame(data, index=index, copy=False)

