            "p2DefenseAbsorbEventCountState",
            "p2DefenseAbsorbEventCount",
            "p2DefenseAbsorbEventCountUnavailableReason",
            "p2DefenseCloseReason",
            "p2DefenseAvailability",
        )
        optional_storage_fields = {
            "p2DefenseMeasurementsUnavailableReason",
            "p2DefenseDurationTicks",
            "p2DefenseWallPresentTicksState",
            "p2DefenseWallPresentTicks",
            "p2DefenseWallPresentTicksUnavailableReason",
            "p2DefenseBuildProxyState",
            "p2DefenseBuildProxy",
            "p2DefenseBuildProxyUnavailableReason",
            "p2DefenseAbsorbProxyState",
            "p2DefenseAbsorbProxy",
            "p2DefenseAbsorbProxyUnavailableReason",
            "p2DefenseSameBandConsistencyState",
            "p2DefenseSameBandConsistency",
            "p2DefenseSameBandConsistencyUnavailableReason",
            "p2DefenseWallEventCountState",
            "p2DefenseWallEventCount",
            "p2DefenseWallEventCountUnavailableReason",
            "p2DefenseBuildEventCountState",
            "p2DefenseBuildEventCount",
            "p2DefenseBuildEventCountUnavailableReason",
            "p2DefenseAbsorbEventCountState",
            "p2DefenseAbsorbEventCount",
            "p2DefenseAbsorbEventCountUnavailableReason",
        }
        column_overrides = {
            "p2DefenseActivitySourceCount": "source_count",
            "p2DefenseActivityFirstSourceRefKind": "first_source_ref_kind",
            "p2DefenseActivityFirstSourceRef": "first_source_ref",
            "p2DefenseActivityLatestSourceRefKind": "latest_source_ref_kind",
            "p2DefenseActivityLatestSourceRef": "latest_source_ref",
            "p2DefenseActivityMembershipSetRef": "membership_set_ref",
        }
        columns = tuple(
            column_overrides.get(
                name,
                name.removeprefix("p2Defense")
                .replace("Activity", "activity_")
                .replace("Measurements", "measurements_")
                .replace("Measurement", "measurement_")
                .replace("Unavailable", "unavailable_")
                .replace("Present", "present_")
                .replace("Event", "event_")
                .lower(),
            )
            for name in storage_fields
        )
        field_paths = {
            column: prefix + storage
            for column, storage in zip(columns, storage_fields)
        }
        optional_columns = tuple(
            column
            for column, storage in zip(columns, storage_fields)
            if storage in optional_storage_fields
        )
        base = self._event_df(
            event,
            _with_optional_paths(field_paths, optional_columns),
            2,
        )
        _restore_optionals(base, optional_columns)
        kinds = self._event_df(
            event, {"value": prefix + "p2DefenseActivityKinds"}, 3
        )
        return _attach(
            base,
            "activity_kinds",
            _parent_groups(kinds, lambda row: _clean(row["value"])),
        )

